#!/usr/bin/env python3
"""SQLI-001 local HTTP verification draft (lab target only)."""
import argparse
import json
import sys
import urllib.error
import urllib.parse
import urllib.request

MARKERS = {
    "login_name": "Your Login name:",
    "password": "Your Password:",
    "sql_error": "SQL syntax",
    "missing_param": "Please input the ID as parameter with numeric value",
}


def load_cookie(session_file):
    if not session_file:
        return None
    with open(session_file, "r", encoding="utf-8") as fh:
        raw = fh.read().strip()
    if not raw:
        return None
    if raw.startswith("{"):
        data = json.loads(raw)
        return data.get("cookie") or data.get("Cookie")
    return raw


def send(base_url, path, test_id, session_file, timeout):
    url = base_url.rstrip("/") + "/" + path.lstrip("/") + "?" + urllib.parse.urlencode({"id": test_id})
    headers = {"User-Agent": "sqli-001-audit/1.0", "Accept": "*/*"}
    cookie = load_cookie(session_file)
    if cookie:
        headers["Cookie"] = cookie
    request = urllib.request.Request(url, headers=headers, method="GET")
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = response.read().decode("utf-8", "replace")
            return {"id": test_id, "http_status": response.status, "body": body}
    except urllib.error.HTTPError as exc:
        return {"id": test_id, "http_status": exc.code, "body": exc.read().decode("utf-8", "replace")}
    except urllib.error.URLError as exc:
        return {"id": test_id, "http_status": None, "body": "", "transport_error": str(exc)}


def summarize(result):
    body = result["body"]
    result["markers"] = {name: (marker in body) for name, marker in MARKERS.items()}
    return result


def main():
    parser = argparse.ArgumentParser(description="SQLI-001 GET id response comparison")
    parser.add_argument("--base-url", required=True, help="target origin, e.g. http://127.0.0.1:8080")
    parser.add_argument("--path", required=True, help="script path, e.g. /sqli/Less-1/index.php")
    parser.add_argument("--id", dest="test_id", default="1'", help="probe value for GET id")
    parser.add_argument("--baseline-id", default="1", help="normal GET id value")
    parser.add_argument("--session-file", default=None, help="optional file with a Cookie header or JSON cookie field")
    parser.add_argument("--timeout", type=float, default=15.0)
    args = parser.parse_args()
    baseline = summarize(send(args.base_url, args.path, args.baseline_id, args.session_file, args.timeout))
    probe = summarize(send(args.base_url, args.path, args.test_id, args.session_file, args.timeout))
    print(json.dumps({"baseline": baseline, "probe": probe}, indent=2, ensure_ascii=False))
    if baseline.get("http_status") != 200:
        print("WARN baseline is not HTTP 200; check --path and PHP deployment", file=sys.stderr)
    if probe.get("markers", {}).get("sql_error") and not baseline.get("markers", {}).get("sql_error"):
        print("OBSERVE probe contains a SQL syntax error marker absent from baseline", file=sys.stderr)
    else:
        print("OBSERVE no probe-specific SQL syntax error marker", file=sys.stderr)


if __name__ == "__main__":
    main()
